const body = $('Webhook').first().json.body || {};
if (!body.project_id) { const e = { valid: false, error: 'project_id obligatorio' }; return [{ json: e }]; }
let photoUrls = body.photo_urls;
if (!photoUrls && body.photo_url) photoUrls = [body.photo_url];
if (!Array.isArray(photoUrls)) photoUrls = [];
photoUrls = photoUrls.filter(u => typeof u === 'string' && u.startsWith('http')).slice(0, 6);
if (photoUrls.length === 0) { const e = { valid: false, error: 'photo_url o photo_urls (>= 1) obligatorio' }; return [{ json: e }]; }
const out = {
  valid: true,
  project_id: body.project_id,
  photo_urls: photoUrls,
  description: (body.description || '').toString().slice(0, 2000),
  location_in_property: (body.location_in_property || '').toString().slice(0, 200),
  inspector: body.inspector || 'arquitecto',
  started_at: Date.now()
};
return [{ json: out }];

const llm = $input.first().json;
const built = $('Build Prompt').first().json;
const content = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content || '';
const usage = llm.usage || {};
const tokensIn = usage.prompt_tokens || 0;
const tokensOut = usage.completion_tokens || 0;
const cost = (tokensIn / 1000) * 0.0025 + (tokensOut / 1000) * 0.01;

let parsed = { findings: [], global_summary: '', confidence: 'low' };
try {
  const m = content.match(/\{[\s\S]*\}/);
  if (m) parsed = JSON.parse(m[0]);
} catch (e) {
  parsed = { findings: [], global_summary: 'parse error: ' + e.message, confidence: 'low' };
}

const findings = Array.isArray(parsed.findings) ? parsed.findings : [];

const out = {
  project_id: built.project_id,
  project_name: built.project_name,
  photo_urls: built.photo_urls,
  description: built.description,
  location_in_property: built.location_in_property,
  inspector: built.inspector,
  findings: findings,
  global_summary: parsed.global_summary || '',
  confidence: parsed.confidence || 'low',
  requires_in_situ_diagnosis: parsed.requires_in_situ_diagnosis === true,
  llm_model: llm.model || 'gpt-4o',
  llm_tokens_in: tokensIn,
  llm_tokens_out: tokensOut,
  llm_cost: Math.round(cost * 100000) / 100000,
  cost_per_finding: findings.length > 0 ? Math.round((cost / findings.length) * 100000) / 100000 : null,
  has_critical: findings.some(f => f && (f.severity === 'critical' || f.severity === 'high' || f.affects_safety === true)),
  high_count: findings.filter(f => f && f.severity === 'high').length,
  critical_count: findings.filter(f => f && f.severity === 'critical').length
};
return [{ json: out }];

const parent = $input.first().json;
return parent.findings.map(f => ({
  json: {
    ...parent,
    pathology_type: f.pathology_type || 'otra',
    severity: f.severity || 'medium',
    urgency: f.urgency || 'programar',
    structural: f.structural === true,
    affects_safety: f.affects_safety === true,
    affects_habitability: f.affects_habitability === true,
    description_finding: f.description || '',
    recommended_action: f.recommended_action || '',
    estimated_cost_min: typeof f.estimated_cost_min === 'number' ? f.estimated_cost_min : null,
    estimated_cost_max: typeof f.estimated_cost_max === 'number' ? f.estimated_cost_max : null,
    requires_specialist: f.requires_specialist === true,
    specialist_type: f.specialist_type || null,
    finding_raw: f
  }
}));

const all = $input.all();
const inserted = all.map(it => it.json).filter(j => j && j.id);
const parent = $('Parse Findings').first().json;
const out = {
  project_id: parent.project_id,
  project_name: parent.project_name,
  inserted_ids: inserted.map(i => i.id),
  total_findings: inserted.length,
  high_count: parent.high_count,
  critical_count: parent.critical_count,
  has_critical: parent.has_critical,
  global_summary: parent.global_summary,
  confidence: parent.confidence,
  requires_in_situ_diagnosis: parent.requires_in_situ_diagnosis,
  photo_urls: parent.photo_urls,
  llm_cost: parent.llm_cost,
  findings_detail: parent.findings
};
return [{ json: out }];

const data = $input.first().json;
const rows = (data.findings_detail || []).map(f => {
  const sev = (f.severity || 'medium').toLowerCase();
  const sevColor = { critical: '#7f1d1d', high: '#dc2626', medium: '#f59e0b', low: '#10b981' }[sev] || '#6b7280';
  const safetyBadge = f.affects_safety ? '<span style="background:#dc2626;color:white;padding:2px 4px;border-radius:3px;font-size:11px">SEGURIDAD</span>' : '';
  const structBadge = f.structural ? '<span style="background:#7c2d12;color:white;padding:2px 4px;border-radius:3px;font-size:11px">ESTRUCTURAL</span>' : '';
  const cost = (f.estimated_cost_min || f.estimated_cost_max) ? (f.estimated_cost_min || 0) + '-' + (f.estimated_cost_max || 0) + 'eur' : 'no estimado';
  return '<tr>' +
    '<td><span style="background:' + sevColor + ';color:white;padding:2px 8px;border-radius:3px;font-weight:bold">' + sev.toUpperCase() + '</span> ' + safetyBadge + ' ' + structBadge + '</td>' +
    '<td><b>' + (f.pathology_type || '?') + '</b><br><small>' + (f.description || '?') + '</small></td>' +
    '<td>' + (f.urgency || '?') + '</td>' +
    '<td>' + cost + '</td>' +
    '<td><small>' + (f.recommended_action || '?') + (f.requires_specialist ? '<br>Especialista: ' + (f.specialist_type || 'sin especificar') : '') + '</small></td>' +
    '</tr>';
}).join('');
const photos = (data.photo_urls || []).map(u => '<a href="' + u + '">foto</a>').join(' &middot; ');
const html = '<h2>Patologías detectadas — ' + (data.project_name || '?') + '</h2>' +
  '<p><b>' + data.total_findings + ' patologías detectadas</b> &middot; ' + data.critical_count + ' críticas &middot; ' + data.high_count + ' altas &middot; confianza: ' + data.confidence + '</p>' +
  '<p>' + (data.global_summary || '') + '</p>' +
  (data.requires_in_situ_diagnosis ? '<p style="color:#dc2626"><b>⚠ Requiere diagnóstico in situ adicional.</b></p>' : '') +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">' +
  '<thead><tr style="background:#f3f4f6"><th>Severidad</th><th>Tipo</th><th>Urgencia</th><th>Coste estimado</th><th>Acción</th></tr></thead>' +
  '<tbody>' + rows + '</tbody></table>' +
  '<p>Fotos: ' + photos + '</p>';
return [{ json: { html: html, project_name: data.project_name, total_findings: data.total_findings, critical_count: data.critical_count, high_count: data.high_count } }];

const err = $input.first().json;
const built = $('Build Prompt').first().json;
const msg = (err && (err.message || (err.error && err.error.message))) || 'vision error';
return [{ json: { project_id: built.project_id, error: msg } }];
